//! Regenerates the committed Ace Server API client (`src/ace_server_api`).
//!
//! The spec is fetched from the local ace-blocker-site dev server
//! (`http://localhost:5173/api/v1/openapi.json`). This tool **fails loudly**
//! when the server is unreachable: silently skipping left the committed
//! client stale with no signal (GEN-01).
//!
//! Note: this is the *remote server's* API, not the engine's own API — the
//! engine's spec lives in `docs/openapi.json` and is regenerated by
//! `gen-openapi-spec`.
use openapi_to_rust::{CodeGenerator, GeneratorConfig, SchemaAnalyzer};
use std::time::Duration;

#[tokio::main]
async fn main() {
    let openapi_url = "http://localhost:5173/api/v1/openapi.json"; // http because invalid certs on localhost

    let client = reqwest::Client::builder()
        .danger_accept_invalid_certs(true)
        .timeout(Duration::from_secs(3))
        .build()
        .unwrap();

    let response = client
        .get(openapi_url)
        .send()
        .await
        .unwrap_or_else(|error| {
            eprintln!(
                "ERROR: could not connect to the OpenAPI spec server at {openapi_url}: {error}.",
            );
            eprintln!(
                "Start the ace-blocker-site dev server first; the committed client must not be \
                 regenerated from a stale or absent spec."
            );
            std::process::exit(1);
        });

    if !response.status().is_success() {
        eprintln!(
            "ERROR: OpenAPI spec server returned status: {}.",
            response.status()
        );
        std::process::exit(1);
    }

    let spec_content = response.text().await.unwrap();

    let spec_value: serde_json::Value =
        serde_json::from_str(&spec_content).expect("Failed to parse OpenAPI JSON");

    let mut analyzer = SchemaAnalyzer::new(spec_value).expect("Failed to initialize analyzer");
    let mut analysis = analyzer.analyze().expect("Failed to analyze schema");

    let config = GeneratorConfig {
        spec_path: std::path::PathBuf::from("openapi.json"),
        output_dir: std::path::PathBuf::from("src/ace_server_api"),
        module_name: "api".to_string(),
        enable_async_client: true,
        ..Default::default()
    };

    let generator = CodeGenerator::new(config);
    let result = generator
        .generate_all(&mut analysis)
        .expect("Failed to generate code");
    generator
        .write_files(&result)
        .expect("Failed to write generated files");

    println!("Successfully generated OpenAPI client to src/ace_server_api");
}
